    public static String getHTML(String host) throws MalformedURLException, UnsupportedEncodingException, IOException {

        String url = "http://" + sanitizeHost(host) + "/";
        BufferedReader in = new BufferedReader(new InputStreamReader(new URL(url).openStream()));
        String inputLine;
        String content = "";
