     * 
     * @param host host a validar
     * @return host validado
     */
    public static String sanitizeHost(String host) {
        Pattern p = Pattern.compile("[^a-zA-Z0-9]");
        Matcher m = p.matcher(host);
        return m.replaceAll("");
    }

    public static void main(String[] args) throws MalformedURLException, UnsupportedEncodingException, IOException {
        Scanner scan = new Scanner(System.in);
        System.out.println("Host: ");
        String host = scan.nextLine();
        if (sanitizeHost(host).length() == 0) {
            System.out.println("Invalid Host");
        } else {
            System.out.println(getHTML(host));
        }
    }
