public class ClassX {
    /**
     * A funkció egy generált URL-ből kéri le a tartalmat a gazda érvényesítése után.
     * 
     * Ez a funkció megtisztítja a gazdát azáltal, hogy ellenőrzi az érvénytelen karaktereket, például a szóközöket.
     */
    public String clean(URL url) {
        String str = url.toString();
        str = str.replaceAll(" ", "%20");
        str = str.replaceAll("=", "%3D");
        str = str.replaceAll("&", "%26");
        str = str.replaceAll("'", "%27");
        str = str.replaceAll("\"", "%22");
        str = str.replaceAll("(", "%28");
        str = str.replaceAll(")", "%29");
        return str;
    }
}
