```java
/**
 * Mengecek jika algoritmanya sesuai.
 * 
 * @param token Header token yang perlu dicek
 * @return true jika algoritmanya sesuai, false jika tidak.
 */
public static boolean checkAlgorithm(Map<String, List<String>> token) {
    List<String> algorithms = token.get("alg");
    if (algorithms == null) {
        return false;
    }
    for (String algorithm : algorithms) {
        if (algorithm.equals("HS256")) {
            return true;
        }
    }
    return false;
}
```

