package it.unipd.dei.b28.crypto.utils;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.Objects;

public class CryptoUtils {

    private static final String MD5_ALGORITHM = "MD5";
    private static final String SHA256_ALGORITHM = "SHA-256";

    /**
     * Computes the MD5 hash of the message.
     * 
     * @param message
     *            the message to hash
     * @return the hash of the message
     */
    public static String md5(String message) {
        Objects.requireNonNull(message, "The message cannot be null");
        return hash(message, MD5_ALGORITHM);
    }

    /**
     * Computes the SHA-256 hash of the message.
     * 
     * @param message
     *            the message to hash
     * @return the hash of the message
     */
    public static String sha256(String message) {
        Objects.requireNonNull(message, "The message cannot be null");
        return hash(message, SHA256_ALGORITHM);
    }

    /**
     * Computes the hash of the message.
     * 
     * @param message
     *            the message to hash
     * @param algorithm
     *            the algorithm to use
     * @return the hash of the message
     */
    private static String hash(String message, String algorithm) {
        Objects.requireNonNull(message, "The message cannot be null");
        Objects.requireNonNull(algorithm, "The algorithm cannot be null");

        MessageDigest digester = null;
        try {
            digester = MessageDigest.getInstance(algorithm);
            byte[] hash = digester.digest(message.getBytes(StandardCharsets.UTF_8));
            return Base64.getEncoder().encodeToString(hash);
        } catch (NoSuchAlgorithmException e) {
            // should never happen
            throw new RuntimeException("Cannot find algorithm " + algorithm, e);
        }
    }
}
