package nl.tudelft.contextproject.controller.admin;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

import javax.servlet.http.HttpServletRequest;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;

import nl.tudelft.contextproject.controller.BaseController;
import nl.tudelft.contextproject.model.Log;
import nl.tudelft.contextproject.service.LogService;

@Controller
public class AdminLogController extends BaseController {

	@Autowired
	private LogService logService;

	@GetMapping("/admin/logs")
	public String list(HttpServletRequest request, Model model) {
		List<Log> logs = logService.findAll();
		model.addAttribute("logs", logs);
		return "admin/logs";
	}

	@GetMapping("/admin/logs/search")
	public String search(HttpServletRequest request, Model model,
			@RequestParam(name = "start", required = false) String start,
			@RequestParam(name = "end", required = false) String end) {
		List<Log> logs = new ArrayList<>();

		if (start == null || end == null) {
			logs = logService.findAll();
		} else {
			LocalDateTime startDateTime = LocalDateTime.parse(start);
			LocalDateTime endDateTime = LocalDateTime.parse(end);
			logs = logService.findByTimeBetween(startDateTime, endDateTime);
		}

		model.addAttribute("logs", logs);
		return "admin/logs";
	}
}
