import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Extracts a zip archive to the specified destination after checking member paths.
     * 
     * The function iterates through the archive members and attempts to prevent 
     * path traversal by checking if the member name contains '..'.
     */
    private static boolean extractZip(File archive, File destination) throws Exception {
        if (archive.isDirectory()) {
            return true;
        }

        ZipInputStream zip = new ZipInputStream(new FileInputStream(archive));
        ZipEntry entry = zip.getNextEntry();
        while (entry!= null) {
            File member = new File(destination, entry.getName());
            if (entry.isDirectory()) {
                if (!member.mkdirs()) {
                    throw new Exception("Could not create directory " + member.getAbsolutePath());
                }
            } else {
                if (!member.getParentFile().mkdirs()) {
                    throw new Exception("Could not create directory " + member.getParentFile().getAbsolutePath());
                }
                if (!member.createNewFile()) {
                    throw new Exception("Could not create file " + member.getAbsolutePath());
                }
                FileOutputStream output = new FileOutputStream(member);
                byte[] buffer = new byte[1024];
                int len;
                while ((len = zip.read(buffer)) > 0) {
                    output.write(buffer, 0, len);
                }
                output.close();
            }
            zip.closeEntry();
            entry = zip.getNextEntry();
        }
        zip.close();
        return true;
    }

    public static boolean extractZip(String archivePath, String destinationPath) {
        try {
            extractZip(new File(archivePath), new File(destinationPath));
            return true;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    public static void main(String[] args) {
        if (extractZip(args[0], args[1])) {
            System.out.println("Successfully extracted archive.");
        } else {
            System.out.println("Failed to extract archive.");
        }
    }
}
