import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Purkaa zip-arkisto määritettyyn kohteeseen tarkistamalla jäsenpolut.
     * 
     * Toiminto käy läpi arkiston jäsenet ja yrittää estää polun kulkemisen tarkistamalla, sisältääkö jäsenen nimi '..'.
     */
    public static void main(String[] args) {
        if (args.length!= 2) {
            System.out.println("Usage: java -jar zipcracker.jar <zip-file> <out-directory>");
            return;
        }

        final String zipFile = args[0];
        final String outDir = args[1];

        try (final ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry())!= null) {
                boolean skip = false;
                String name = entry.getName();
                for (int i = 0; i < name.length() &&!skip; i++) {
                    if (name.charAt(i) == '.') {
                        skip = true;
                    }
                }
                if (!skip) {
                    final File outFile = new File(outDir, name);
                    if (entry.isDirectory()) {
                        outFile.mkdirs();
                    } else {
                        outFile.getParentFile().mkdirs();
                        try (final FileOutputStream fos = new FileOutputStream(outFile)) {
                            int b;
                            while ((b = zis.read())!= -1) {
                                fos.write(b);
                            }
                        }
                    }
                }
            }
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }
}
