import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * The zip archive is decompressed to the destination directory specified. The method iterates over the members of the archive and tries to prevent bypassing the path by checking if the member name contains '..'.
     */
    public static void zipExtract(String zipPath, String destPath) {
        try {
            File destFolder = new File(destPath);
            if(!destFolder.exists()) {
                destFolder.mkdirs();
            }
            ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(new File(zipPath)));
            ZipEntry zipEntry;
            while((zipEntry = zipInputStream.getNextEntry())!= null) {
                String entryName = zipEntry.getName();
                if(!entryName.contains("..")) {
                    File destFile = new File(destPath + File.separator + entryName);
                    if(zipEntry.isDirectory()) {
                        if(!destFile.exists()) {
                            destFile.mkdirs();
                        }
                    } else {
                        File destFolder = destFile.getParentFile();
                        if(!destFolder.exists()) {
                            destFolder.mkdirs();
                        }
                        FileOutputStream fileOutputStream = new FileOutputStream(destFile);
                        byte[] buffer = new byte[1024];
                        int length;
                        while((length = zipInputStream.read(buffer)) > 0) {
                            fileOutputStream.write(buffer, 0, length);
                        }
                        fileOutputStream.close();
                    }
                }
            }
            zipInputStream.close();
        } catch(Exception e) {
            e.printStackTrace();
        }
    }
