import java.util.stream.Stream;

import com.github.austin_powers.java_quiz.quiz.Question;
import com.github.austin_powers.java_quiz.quiz.Question.QuestionType;

public class Quiz {
	private static final String QUESTION_DIRECTORY = "quiz";
	private static final String QUESTION_SUFFIX = ".txt";

	private static final Optional<List<Question>> questionStore = Optional.empty();

	public static List<Question> getQuestions() {
		if (questionStore.isPresent()) {
			return questionStore.get();
		}

		try {
			Stream<File> files = Files.list(Paths.get(QUESTION_DIRECTORY));
			List<File> filesList = files.filter(file -> file.getName().endsWith(QUESTION_SUFFIX)).collect(Collectors.toList());

			List<Question> questions = filesList.stream().map(file -> {
				try {
					return new Question(file.toPath().toAbsolutePath().toString(), QuestionType.valueOf(file.getName().substring(0, file.getName().length() - QUESTION_SUFFIX.length())));
				} catch (IllegalArgumentException e) {
					throw new RuntimeException(e);
				}
			}).collect(Collectors.toList());

			questionStore = Optional.of(questions);
			return questions;
		} catch (IOException e) {
			throw new RuntimeException(e);
		}
	}
}
