    private static final Logger logger = Logger.getLogger(SourceCodeReader.class);

    public static List<String> read(File file) {
        List<String> lines = new ArrayList<String>();
        try {
            BufferedReader br = new BufferedReader(new FileReader(file));
            String line;
            while ((line = br.readLine())!= null) {
                String trimmedLine = line.trim();
                if (trimmedLine.isEmpty()) {
                    continue;
                }
                lines.add(trimmedLine);
            }
            br.close();
        } catch (IOException e) {
            logger.error("Could not read source code from: " + file.getAbsolutePath(), e);
        }
        return lines;
    }

    public static String getLanguageFromFileName(String fileName) {
        String extension = FilenameUtils.getExtension(fileName);
        if (extension.equals("java")) {
            return "Java";
        } else if (extension.equals("cpp") || extension.equals("c")) {
            return "C";
        } else if (extension.equals("php")) {
            return "PHP";
        } else if (extension.equals("py")) {
            return "Python";
        } else if (extension.equals("cs")) {
            return "C#";
        } else if (extension.equals("pl")) {
            return "Perl";
        } else if (extension.equals("js")) {
            return "JavaScript";
        } else if (extension.equals("sql")) {
            return "SQL";
        } else if (extension.equals("rb")) {
            return "Ruby";
        } else {
            return "Unknown";
        }
    }

