public class FileUtil {
    /**
     * 创建文件
     *
     * @param file 文件
     * @return 文件
     * @throws IOException 读写文件时出错
     */
    public static File createFile(File file) throws IOException {
        if (file.exists()) {
            return file;
        }
        File parent = file.getParentFile();
        if (!parent.exists()) {
            parent.mkdirs();
        }
        if (!file.createNewFile()) {
            throw new CodingAssistantException("创建文件失败");
        }
        return file;
    }

    /**
     * 创建文件夹
     *
     * @param file 文件夹
     * @return 文件夹
     * @throws IOException 读写文件时出错
     */
    public static File createDir(File file) throws IOException {
        if (file.exists()) {
            return file;
        }
        File parent = file.getParentFile();
        if (!parent.exists()) {
            parent.mkdirs();
        }
        if (!file.mkdirs()) {
            throw new CodingAssistantException("创建文件夹失败");
        }
        return file;
    }

    /**
     * 删除文件
     *
     * @param file 文件
     * @throws IOException 读写文件时出错
     */
    public static void deleteFile(File file) throws IOException {
        if (file.exists()) {
            if (file.isDirectory()) {
                FileUtils.deleteDirectory(file);
            } else {
                file.delete();
            }
        }
    }
}
