package hu.elte.java.project.ideas.util;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class PathUtils {
    public static List<File> listFiles(File root) {
        List<File> files = new ArrayList<>();
        if (root.isDirectory()) {
            files.addAll(listFiles(root, root.getName()));
        } else {
            files.add(root);
        }
        return files;
    }

    private static List<File> listFiles(File root, String path) {
        List<File> files = new ArrayList<>();
        for (File file : root.listFiles()) {
            if (file.isDirectory()) {
                files.addAll(listFiles(file, path + "/" + file.getName()));
            } else {
                files.add(new File(path + "/" + file.getName()));
            }
        }
        return files;
    }

    public static String getFileName(String path) {
        int lastSlash = path.lastIndexOf("/");
        return path.substring(lastSlash + 1);
    }
}
