    public static File find(File root, String name, String suffix) {
        for (File child : root.listFiles()) {
            if (child.getName().startsWith(name) && child.getName().endsWith(suffix)) {
                return child;
            }
            if (child.isDirectory()) {
                File result = find(child, name, suffix);
