package fr.umlv.poo.java;

import java.io.File;

public class Main {
	public static void main(String[] args) {
        if (args.length!= 1) {
            System.out.println("Usage: java Main file");
            return;
        }

        File file = new File(args[0]);
        if (!file.exists()) {
            System.out.println("File not found");
            return;
        }
        if (!file.isFile()) {
            System.out.println("This is not a file");
            return;
        }
        if (!file.canRead()) {
            System.out.println("Can't read this file");
            return;
        }

        String name = file.getName();
        String extension = file.getName().substring(name.lastIndexOf('.'));
        if (extension.equals(".class")) {
            System.out.println("This is a class file");
        } else {
            System.out.println("This is not a class file");
        }
	}
}
