import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import parser.enums.TokenType;

/**
 * A Token represents a single token of the text.
 * 
 * @author 
 */
public class Token {
	private String text;
	private TokenType type;
	private int start;
	private int end;

	public Token(String text, TokenType type, int start, int end) {
		this.text = text;
		this.type = type;
		this.start = start;
		this.end = end;
	}

	public String getText() {
		return text;
	}

	public TokenType getType() {
		return type;
	}

	public int getStart() {
		return start;
	}

	public int getEnd() {
		return end;
	}

	public String toString() {
		return text;
	}

	public static List<TokenType> getAllTokenTypes() {
		return Arrays.asList(TokenType.values());
	}

	public static List<TokenType> getAllowedTokenTypes() {
		List<TokenType> result = new ArrayList<TokenType>();
		result.addAll(Arrays.asList(TokenType.values()));
		result.removeAll(Arrays.asList(TokenType.COMMENT, TokenType.NEWLINE, TokenType.SPACE));
		return result;
	}

	public static List<TokenType> getAllowedCommentTokenTypes() {
		List<TokenType> result = new ArrayList<TokenType>();
		result.addAll(Arrays.asList(TokenType.values()));
		result.removeAll(Arrays.asList(TokenType.NEWLINE, TokenType.SPACE));
		return result;
	}
}
