package edu.cmu.cs.compilers.hw4.ast;

import edu.cmu.cs.compilers.hw4.visitors.Visitor;

/**
 * PrintStmt ::= "print" "(" Expr ")"
 */
public class PrintStmt extends Stmt {
    Expr expr;

    public PrintStmt(Loc loc, Expr expr) {
        super(loc);
        this.expr = expr;
    }

    public <T, R> R accept(Visitor<T, R> v, T arg) {
        return v.visit(this, arg);
    }

    @Override
    public String toString() {
        return "print(" + expr + ")";
    }
}
