package edu.cmu.cs.compilers.hw4.ast;

import edu.cmu.cs.compilers.hw4.visitors.Visitor;

import java.util.List;

/**
 * Expr ::= "+" Expr Expr | "-" Expr Expr | "*" Expr Expr | "/" Expr Expr | "%" Expr Expr |
 *         "!" Expr | "-" Expr | "not" Expr | "(" Expr ")" | Literal | Var | "(" "if" Expr "then"
 *         Expr "else" Expr ")" | "(" "while" Expr "do" Stmt ")" | "(" "for" Var "=" Expr "to" Expr
 *         "step" Expr "do" Stmt ")" | "print" "(" Expr ")" | "input" "(" Var ")" |
 *         "mailcap" "(" Var ")" | "system" "(" Var ")" | "(" "+" Expr Expr ")"
 */
public abstract class Expr extends ASTNode {
    public Expr(Loc loc) {
        super(loc);
    }

    abstract public <T, R> R accept(Visitor<T, R> v, T arg);

    @Override
    public String toString() {
        return "(expr)";
    }
}
