import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ClassX {
    /**
     * Mensimulasikan fungsi mailcap.findmatch.
     * Membangun perintah untuk melihat file berdasarkan mime_type dan mengeksekusinya.
     * 
     * Implementasi ini mencakup pemeriksaan untuk mencegah penggabungan perintah dengan memblokir
     * tanda titik koma.
     */
    public static String findMatch(String mime_type, String cmd) {
        if (mime_type.contains(",")) {
            mime_type = mime_type.split(",")[0];
        }

        if (cmd.contains(";")) {
            cmd = cmd.split(";")[0];
        }

        String cmd_file = "/usr/bin/file";
        try {
            Process process = Runtime.getRuntime().exec(cmd_file + " -b " + mime_type);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine())!= null) {
                if (line.contains("text")) {
                    return cmd;
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return null;
    }

    public static void main(String[] args) {
        String mime_type = args[0];
        String cmd = args[1];
        String result = findMatch(mime_type, cmd);
        if (result!= null) {
            try {
                Process process = Runtime.getRuntime().exec(result);
                process.waitFor();
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}

