                continue;
            String command = split[2];
            Matcher matcher = Pattern.compile("([^/]+)$").matcher(command);
            File f = null;
            if (matcher.find()) {
                String file = matcher.group(1);
                f = new File(file);
            }
            if (f!= null && f.exists()) {
                System.out.println(f.getAbsolutePath());
