package hu.axxs.javasimulator.instruction.builtin;

import hu.axxs.javasimulator.environment.Environment;
import hu.axxs.javasimulator.instruction.exception.InstructionException;
import hu.axxs.javasimulator.instruction.exception.InstructionParseException;
import hu.axxs.javasimulator.instruction.util.InstructionParser;
import hu.axxs.javasimulator.instruction.util.InstructionParser.InstructionParserResult;

import java.io.PrintStream;

public class BuiltinPrintInstruction extends BuiltinInstruction {

    private final PrintStream printStream;
    private final String format;

    public BuiltinPrintInstruction(PrintStream printStream, String format) {
        this.printStream = printStream;
        this.format = format;
    }

    @Override
    protected void perform(Environment environment) throws InstructionException {
        try {
            InstructionParserResult result = InstructionParser.parse(format, environment);
            printStream.print(result.formattedText);
        } catch (InstructionParseException e) {
            throw new InstructionException(e);
        }
    }
