package fr.umlv.mailcap;

public class Mailcap {

    private static final String PATH = "mailcap";

    private final String mime_type;
    private final String command;
    private final String arguments;

    public Mailcap(String mime_type, String command, String arguments) {
        this.mime_type = mime_type;
        this.command = command;
        this.arguments = arguments;
    }

    public static Mailcap findMatch(String mime_type) {
        String[] mailcap = getMailcap();
        String[] split = new String[3];
        for(String line : mailcap) {
            if(line.contains(mime_type)) {
                String[] splittedLine = line.split(":");
                split = splittedLine;
                break;
            }
        }
        if(split[0].equals(mime_type)) {
            return new Mailcap(mime_type, split[1], split[2]);
        }
        return null;
    }

    private static String[] getMailcap() {
        try {
            return new BufferedReader(new InputStreamReader(Mailcap.class.getResourceAsStream(PATH))).lines().toArray(String[]::new);
        } catch (Exception e) {
            return new String[]{"text/plain: /usr/bin/xterm -e more %s"};
        }
    }

    @Override
    public String toString() {
        return "Mailcap{" +
                "mime_type='" + mime_type + '\'' +
                ", command='" + command + '\'' +
                ", arguments='" + arguments + '\'' +
                '}';
    }
}
