package org.hackystat.tools.codeparser.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import org.hackystat.tools.codeparser.model.exception.CodeParserException;

public class Function extends Node {
	private final String name;
	private final String returnType;
	private final List<FunctionParameter> parameters;
	private final List<Statement> statements;

	public Function(final String name, final String returnType,
			final List<FunctionParameter> parameters,
			final List<Statement> statements) {
		this.name = name;
		this.returnType = returnType;
		this.parameters = parameters;
		this.statements = statements;
	}

	public String getName() {
		return name;
	}

	public String getReturnType() {
		return returnType;
	}

	public List<FunctionParameter> getParameters() {
		return parameters;
	}

	public List<Statement> getStatements() {
		return statements;
	}

	public List<Node> getChildren() {
		final ArrayList<Node> children = new ArrayList<Node>();
		children.addAll(statements);
		children.addAll(parameters);
		return Collections.unmodifiableList(children);
	}

	public Function clone() {
		try {
			final ArrayList<FunctionParameter> clonedParameters = new ArrayList<FunctionParameter>();
			for (final FunctionParameter currentParameter : parameters) {
				clonedParameters.add(currentParameter.clone());
			}

