		Maze maze = mazes.get(mazeName);
		if (maze == null) {
			maze = createMaze(mazeName);
			mazes.put(mazeName, maze);
		}
		return maze;
	}

	// Maakt een maze aan op basis van een bestaande maze
	private static Maze createMaze(String mazeName) {
		InputStream is = MazeFactory.class.getResourceAsStream(mazeName);
		BufferedReader reader = new BufferedReader(new InputStreamReader(is));
		String line = null;
		List<Cell> rows = new ArrayList<Cell>();
		try {
			while ((line = reader.readLine())!= null) {
				rows.add(createRow(line));
			}
		} catch (IOException e) {
			e.printStackTrace();
		}
		return new Maze(rows);
	}

	// Maakt een rij aan op basis van de bestaande rij
	private static Cell createRow(String line) {
		return new Cell(line);
	}
