class Mailcap {

    /**
     * Проверява дали дадена команда се изпълнява.
     * @param command команда, която да се изпълни.
     * @return true, ако команда може да се изпълни.
     */
    public static boolean isSafeCommand(String command) {
        return!command.contains("\\.") &&!command.contains("\\.");
    }

    /**
     * Взима mime_type от входния файл.
     * @param filename път към входния файл.
     * @return mime_type на файла.
     */
    public static String getMimeType(String filename) {
        return filename.substring(filename.lastIndexOf('.') + 1);
    }

    /**
     * Симулира функцията mailcap.findmatch.
     * Конструира команда за преглед на файла въз основа на mime_type и я изпълнява.
     * @param mime_type mime_type на файла.
     * @param filename път към файла.
     * @return резултат от изпълнението на команда.
     */
    public static String findMatch(String mime_type, String filename) {
        String command = "mailcap -s \"" + mime_type + "\" \"" + filename + "\"";
        try {
            Process p = Runtime.getRuntime().exec(command);
            BufferedReader br = new BufferedReader(
                    new InputStreamReader(p.getInputStream()));
            String line = br.readLine();
            if (line!= null) {
                return line;
            }
        } catch (Exception e) {
        }
        return "ERROR";
    }

    public static void main(String[] args) {
        try {
            BufferedReader br = new BufferedReader(
