package com.softuni.homework.advanced.exam.exam2;

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        Pattern pattern = Pattern.compile("^(.*?)\\s+(?<type>[A-Z]+?)\\s+(?<name>[\\w]+?)\\s*=\\s*\\{\\s*(?<requirements>.*?)\\s*\\}\\s*$");
        List<String> result = new ArrayList<>();

        int n = Integer.parseInt(sc.nextLine());

        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();

            Matcher matcher = pattern.matcher(line);

            if (matcher.find()) {
                String name = matcher.group("name");
                String type = matcher.group("type");
                String requirements = matcher.group("requirements");

                String[] requirementsSplit = requirements.split(", ");

                int[] requirementsNumbers = new int[requirementsSplit.length];

                for (int j = 0; j < requirementsSplit.length; j++) {
                    requirementsNumbers[j] = Integer.parseInt(requirementsSplit[j]);
                }

                result.add(String.format("%s - %s", name, type));

                for (int k = 0; k < requirementsNumbers.length; k++) {
                    result.add(String.format("-%s", requirementsNumbers[k]));
                }
            }
        }

        for (String s : result) {
            System.out.println(s);
        }
    }
}
