/**
 * Een test file.
 * 
 * @author 
 */
public class TestFile {
    private FileItem file;
    private List<Test> tests;

    /**
     * Maak een nieuwe test file aan met de opgegeven parameters.
     * 
     * @param file
     *            De file waar de test file naartoe geschreven moet worden.
     * @param tests
     *            De tests die moeten worden toegevoegd aan de file.
     */
    public TestFile(FileItem file, List<Test> tests) {
        this.file = file;
        this.tests = tests;
    }

    /**
     * Schrijf de test file naar de bestandsbasis.
     * 
     * @throws IOException
     *             Wanneer er iets mis gaat met het schrijven.
     */
    public void writeFile() throws IOException {
        FileWriter fw = new FileWriter(file.getFile(), true);
        BufferedWriter bw = new BufferedWriter(fw);

        StringBuilder sb = new StringBuilder();
        for (Test test : tests) {
            sb.append(test.toString()).append("\r\n");
        }
        bw.write(sb.toString());

        bw.close();
    }
}
