    }

    @Override
    public TaskResult solve() {
        final String OUTPUT_FILENAME = "Task08-out.txt";
        final String INPUT_FILENAME = "Task08-in.txt";

        try (BufferedReader in = new BufferedReader(new InputStreamReader(new FileInputStream(INPUT_FILENAME)));
             BufferedWriter out = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(OUTPUT_FILENAME)))) {
            String line = in.readLine();
            while (line!= null) {
                out.write("Line:\n" + line + "\n");
                out.write("Reverse:\n" + reverse(line) + "\n");
                line = in.readLine();
            }
        } catch (IOException e) {
            return TaskResult.failure(e);
        }

        return TaskResult.success(OUTPUT_FILENAME);
    }

    private String reverse(String line) {
        StringBuilder sb = new StringBuilder();
        for (int i = line.length() - 1; i >= 0; --i) {
            sb.append(line.charAt(i));
        }
        return sb.toString();
    }
}
