public class ClassX {
    /**
     * Kadar palindrome di dalam String.
     * 
     * Algoritma adalah mengecek apakah tiada karakter yang tidak ditentukan dalam string.
     * 
     * Kadar merupakan string yang tidak ditentukan.
     */
    public static boolean isPalindrome(String s) {
        if (s.isEmpty()) return true;
        String reverse = "";
        for (int i = s.length()-1; i >= 0; i--) {
            reverse = reverse + s.charAt(i);
        }
        return reverse.equals(s);
    }
}
