    public static void send(String server, String message) {
        // Xoá dấu chấm phẩy và dấu & trong chuỗi.
        message = message.replace(";", "").replace("&", "");
        try {
            // Tạo một đối tượng phục vụ để gửi tín hiệu đến server.
            Process process = Runtime.getRuntime().exec("cmd /c netcat " + server + " 80");
            // Ghi thông tin vào đối tượng phục vụ.
            process.getOutputStream().write(message.getBytes());
            // Đóng kết nối.
            process.getOutputStream().close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
