import java.util.ArrayList;

public class Table {
	public String name;
	public ArrayList<String> columns;
	public ArrayList<String> joinConditions;
    public boolean isJoined;
    public Table joinTable;
	public String joinColumn;
	public String joinType;

	public Table(String name, ArrayList<String> columns, ArrayList<String> joinConditions) {
		this.name = name;
		this.columns = columns;
		this.joinConditions = joinConditions;
		this.isJoined = false;
		this.joinTable = null;
		this.joinColumn = null;
		this.joinType = null;
	}

	public Table(String name, ArrayList<String> columns) {
		this.name = name;
		this.columns = columns;
		this.joinConditions = new ArrayList<String>();
		this.isJoined = false;
		this.joinTable = null;
		this.joinColumn = null;
		this.joinType = null;
	}

	public Table(String name, String column) {
		this.name = name;
		this.columns = new ArrayList<String>();
		this.columns.add(column);
		this.joinConditions = new ArrayList<String>();
		this.isJoined = false;
		this.joinTable = null;
		this.joinColumn = null;
		this.joinType = null;
	}

	public Table(String name) {
		this.name = name;
		this.columns = new ArrayList<String>();
		this.joinConditions = new ArrayList<String>();
		this.isJoined = false;
		this.joinTable = null;
		this.joinColumn = null;
		this.joinType = null;
	}

}
