package com.github.thomasdarimont.codewars.katas.kata.kata8kyu;

import java.util.Arrays;

public class SumOfPositive {
    public static long sum(long[] arr) {

        long result = 0;

        for (long num : arr) {
            if (num > 0) {
                result += num;
            }
        }

        return result;
    }

    public static long sum2(long[] arr) {
        return Arrays.stream(arr).filter(num -> num > 0).sum();
    }
}
