import com.github.jknack.handlebars.Handlebars;
import com.github.jknack.handlebars.Template;
import com.github.jknack.handlebars.io.ClassPathTemplateLoader;

import java.io.IOException;
import java.util.Map;

public class JavaTemplate {

    private final Template template;

    public JavaTemplate(final String templateName) throws IOException {

        this.template = new Handlebars().registerTemplateLoader(new ClassPathTemplateLoader()).compile(templateName);
    }

    public String render(final Map<String, Object> context) {

        final Context c = Context.newBuilder(context).build();

        try {
            return template.apply(c);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}
