    private List<String> stack;

    /**
     * Constructor.
     */
    public Stack() {
        stack = new LinkedList<String>();
    }

    /**
     * <code>push</code> an item to the stack.
     * 
     * This method is used to add an item to the stack.
     * 
     * @param item the item to be added to the stack.
     */
    public void push(String item) {
        stack.add(item);
    }

    /**
     * <code>pop</code> an item from the stack.
     * 
     * This method is used to remove an item from the stack.
     * 
     * @return the item that was removed.
     */
    public String pop() {
        return stack.remove(stack.size() - 1);
    }

    /**
     * <code>peek</code> an item from the stack.
     * 
     * This method is used to get the top item in the stack.
     * 
     * @return the item that is at the top of the stack.
     */
    public String peek() {
        return stack.get(stack.size() - 1);
    }

