public class Help {

    public static Help instance;

    public static Help getInstance() {
        if (instance == null) {
            instance = new Help();
        }
        return instance;
    }

    public List<HelpItem> getHelpItems(String dir) {
        List<HelpItem> helpItems = new ArrayList<>();
        File directory = new File(dir);
        for (File file : directory.listFiles()) {
            String name = file.getName();
            int index = name.indexOf(".");
            if (index > 0) {
                name = name.substring(0, index);
            }
            HelpItem helpItem = new HelpItem();
            helpItem.setName(name);
            helpItem.setPath(file.getPath());
            helpItem.setLines(Utils.getLines(file.getPath()));
            helpItems.add(helpItem);
        }
        return helpItems;
    }
}
