package codewars.kyu7;

import java.util.HashMap;
import java.util.Map;

public class RomanNumeralsHelper {

    private static final Map<Integer, String> romans = new HashMap<>();
    static {
        romans.put(1000, "M");
        romans.put(900, "CM");
        romans.put(500, "D");
        romans.put(400, "CD");
        romans.put(100, "C");
        romans.put(90, "XC");
        romans.put(50, "L");
        romans.put(40, "XL");
        romans.put(10, "X");
        romans.put(9, "IX");
        romans.put(5, "V");
        romans.put(4, "IV");
        romans.put(1, "I");
    }

    public static String solution(int n) {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, String> entry : romans.entrySet()) {
            while(n >= entry.getKey()) {
                sb.append(entry.getValue());
                n -= entry.getKey();
            }
        }
        return sb.toString();
    }
}
