```java
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        processa(args);
    }

    private static void processa(String[] args) throws Exception {
        if (args.length < 1) {
            throw new Exception("Favor informar o arquivo");
        }

        final File file = new File(args[0]);
        final FileReader fr = new FileReader(file);
        final BufferedReader br = new BufferedReader(fr);
        String linha;
        while ((linha = br.readLine())!= null) {
            System.out.println(linha);
        }
    }
}
```

#### 1.4.2. Identifique a vulnerabilidade

A vulnerabilidade é na função `processa()`.

#### 1.4.3. Aplique a correção

```java
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        processa(args);
    }

    private static void processa(String[] args) throws Exception {
        if (args.length < 1) {
            throw new Exception("Favor informar o arquivo");
        }

        final File file = new File(args[0]);
        final FileReader fr = new FileReader(file);
        final BufferedReader br = new BufferedReader(fr);
        String linha;
        while ((linha = br.readLine())!= null) {
            if (linha.contains("UNION")) {
                throw new Exception("Você não pode usar a palavra-chave UNION");
            }
            System.out.println(linha);
        }
    }
}
```

