package com.github.shirdrn.game.model;

import com.github.shirdrn.game.model.exception.CardException;

public class Card {
    private final CardType type;
    private final int number;

    public Card(CardType type, int number) {
        this.type = type;
        this.number = number;
    }

    public CardType getType() {
        return type;
    }

    public int getNumber() {
        return number;
    }

    public int getCardNumber() {
        return type.ordinal() * 10 + number;
    }

    public void checkCardNumber(int cardNumber) throws CardException {
        if (cardNumber!= getCardNumber()) {
            throw new CardException("Card number is not valid.");
        }
    }

    @Override
    public int hashCode() {
        final int prime = 31;
        int result = 1;
        result = prime * result + number;
        result = prime * result + type.ordinal();
        return result;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj)
            return true;
        if (obj == null)
            return false;
        if (getClass()!= obj.getClass())
            return false;
        Card other = (Card) obj;
        if (number!= other.number)
            return false;
        if (type!= other.type)
            return false;
        return true;
    }

    @Override
    public String toString() {
        return type.toString() + number;
    }
}
