public class Main {

    public static void main(String[] args) throws IOException {
        if (args.length!= 1) {
            System.out.println("Usage:./nebulae.jar <path-to-repo>");
            System.exit(1);
        }

        System.out.println("Cloning repository...");
        Path path = Paths.get(args[0]);
        File localRepo = new File(path.toString());
        FileRepositoryBuilder builder = new FileRepositoryBuilder();
        Repository repository = builder.setGitDir(localRepo).readEnvironment().findGitDir().build();
        Git git = new Git(repository);
        git.clone().setURI("https://github.com/JuanMard/nebulae.git").setCloneAllBranches(true).setDirectory(localRepo).call();

        System.out.println("Cleaning old data...");
        File data = Paths.get(localRepo.getAbsolutePath(), "data").toFile();
        if (data.exists()) {
            Files.walk(data.toPath()).sorted(Path::compareTo).map(Path::toFile).forEach(File::delete);
        }

        System.out.println("Starting server...");
        Server.main(null);
    }

}


