    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        int k = sc.nextInt();
        int[] count = new int[k];
        for (int i = 0; i < n; i++) {
            count[arr[i] % k]++;
        }

        int ans = 0;
        for (int i = 0; i < k; i++) {
            if (i == 0 || i == k - 1)
                ans += count[i] * (count[i] - 1) / 2;
            else
                ans += count[i] * count[k - i];
        }

        System.out.println(ans);
    }
