package com.github.kostyantyn.codeevaluator.app.service.impl;

import com.github.kostyantyn.codeevaluator.app.dto.CodeEvalRequest;
import com.github.kostyantyn.codeevaluator.app.dto.CodeEvalResult;
import com.github.kostyantyn.codeevaluator.app.exception.CodeEvaluatorException;
import com.github.kostyantyn.codeevaluator.app.service.CodeEvaluatorService;
import com.github.kostyantyn.codeevaluator.app.service.CodeEvaluatorSystemService;
import com.github.kostyantyn.codeevaluator.app.service.CodeEvaluatorUserService;
import com.github.kostyantyn.codeevaluator.app.service.CodeEvaluatorUserSystemService;
import com.github.kostyantyn.codeevaluator.app.service.CodeEvaluatorUserSystemServiceFactory;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

@Service
@Slf4j
@RequiredArgsConstructor
public class CodeEvaluatorServiceImpl implements CodeEvaluatorService {

    private final CodeEvaluatorUserService codeEvaluatorUserService;
    private final CodeEvaluatorUserSystemServiceFactory codeEvaluatorUserSystemServiceFactory;

    @Override
    public CodeEvalResult evaluateCode(CodeEvalRequest codeEvalRequest) {
        try {
            return codeEvaluatorUserService.evaluateCode(codeEvalRequest);
        } catch (CodeEvaluatorException codeEvaluatorException) {
            log.error("Failed to evaluate code", codeEvaluatorException);
            throw codeEvaluatorException;
        }
    }

    @Override
    public CodeEvalResult evaluateCode(String code, String language) {
        try {
            var codeEvaluatorUserSystemService = codeEvaluatorUserSystemServiceFactory.create(language);
            return codeEvaluatorUserSystemService.evaluateCode(code);
        } catch (CodeEvaluatorException codeEvaluatorException) {
            log.error("Failed to evaluate code", codeEvaluatorException);
            throw codeEvaluatorException;
        }
    }
}
