package com.github.hengyunabc.learn.leetcode.question;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * 1086. 前五科的均分
 *
 * @author hengyunabc 2020-03-15 00:08:16
 */
public class P1086HighFive {

    public int[][] highFive(int[][] items) {
        Map<Integer, List<Integer>> map = new HashMap<>();
        for (int[] item : items) {
            int id = item[0];
            int score = item[1];
            List<Integer> list = map.getOrDefault(id, new ArrayList<>());
            list.add(score);
            map.put(id, list);
        }
        int[][] result = new int[map.size()][2];
        int i = 0;
        for (Map.Entry<Integer, List<Integer>> entry : map.entrySet()) {
            List<Integer> list = entry.getValue();
            int sum = 0;
            for (int score : list) {
                sum += score;
            }
            int average = sum / 5;
            result[i][0] = entry.getKey();
            result[i][1] = average;
            i++;
        }
        Arrays.sort(result, Comparator.comparingInt(a -> a[0]));
        return result;
    }
}
