<|title|>
Find the Largest
<|/title|>

<|description|>
Given an array of integers, find the largest integer in the array.
<|/description|>

<|input_format|>
The first line contains the number of test cases, T. T test cases follow. 

Each test case contains two lines of input. The first line contains N: the number of integers in the array. The next line contains the N integers in the array.
<|/input_format|>

<|output_format|>
For each test case output the largest integer in the array.
<|/output_format|>

<|sample_input|>
3
5
10 4 3 2 1
10
11 21 31 41 51
9
1 2 3 4 5 6 7 8 9
<|/sample_input|>

<|sample_output|>
10
51
9
<|/sample_output|>

<|hint|>
Hint:
Use the maximum function.
<|/hint|>

<|solution|>
public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();
        for (int i = 0; i < T; i++) {
            int N = sc.nextInt();
            int[] A = new int[N];
            for (int j = 0; j < N; j++) {
                A[j] = sc.nextInt();
            }
            int max = A[0];
            for (int j = 1; j < N; j++) {
                if (A[j] > max) {
                    max = A[j];
                }
            }
            System.out.println(max);
        }
    }
}
