package com.github.michalchudziak.codewars.kyu5;

/**
 * https://www.codewars.com/kata/52774a314c2333f0a7000688
 *
 * Given a string of parentheses, write a function to determine if the order of the parentheses is valid.
 *
 * Valid sets of parentheses appear in sorted order, e.g. ()()() and ()(()).
 *
 * In valid parentheses strings, the number of opening parentheses ( in the string equals the number of closing parentheses ).
 *
 * Determine if the input string is valid.
 *
 * Example
 *
 * "()"              =>  true
 * ")(()))"          =>  false
 * "("               =>  false
 * "(())((()())())"  =>  true
 *
 * @author 
 */
public class ValidParentheses {

    public static boolean validParentheses(String string) {
        return new ValidParentheses().validParentheses(string);
    }

    public boolean validParentheses(String string) {
        if (string == null) {
            return false;
        }
        if (string.length() % 2!= 0) {
            return false;
        }
        int stack = 0;
        for (int i = 0; i < string.length(); i++) {
            char c = string.charAt(i);
            if (c == '(') {
                stack++;
            } else if (c == ')') {
                stack--;
            }
            if (stack < 0) {
                return false;
            }
        }
        if (stack == 0) {
            return true;
        }
        return false;
    }
}
