    int start = content.indexOf("<script");
    while (start >= 0) {
        int end = content.indexOf("</script>", start);
        if (end < 0) {
            throw new IllegalArgumentException("Missing </script> tag.");
        }
        content = content.substring(0, start) + content.substring(end + 9);
        start = content.indexOf("<script");
    }
    return content;
}
