    public int minOperations(String s) {
        int[] count = new int[26];
        for (char c : s.toCharArray()) {
            count[c - 'a']++;
        }
        int min = Integer.MAX_VALUE;
        for (int i = 0; i < 26; i++) {
            min = Math.min(min, count[i]);
        }
        return s.length() - min * 2;
    }
