    @Id
    @GeneratedValue
    private Long id;
    private String name;
    private String description;
    private String image;
    private String price;
    private String tags;
    private String category;

    private JpsItem() {
    }

    public JpsItem(String name, String description, String image, String price, String tags, String category) {
        this.name = name;
        this.description = description;
        this.image = image;
        this.price = price;
        this.tags = tags;
        this.category = category;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getDescription() {
        return description;
    }

    public String getImage() {
        return image;
    }

    public String getPrice() {
        return price;
    }

    public String getTags() {
        return tags;
    }

    public String getCategory() {
        return category;
    }

    public static JpsItemFactory factory = new JpsItemFactory();

}
