package com.github.javaguru.codewars.kata.fifth;

import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class KataFifth {
    public static String solution(String str) {
        Map<Character, Integer> charCount = new HashMap<>();

        for (char c : str.toCharArray()) {
            charCount.put(c, charCount.getOrDefault(c, 0) + 1);
        }

        return charCount
               .entrySet()
               .stream()
               .sorted((e1, e2) -> e2.getValue() - e1.getValue())
               .map(e -> e.getKey() + e.getValue())
               .collect(Collectors.joining());
    }

    public static void main(String[] args) {
        System.out.println(solution("aaabbbccc"));
        System.out.println(solution("abcccccccd"));
        System.out.println(solution("abcdefghijklmnopqrstuvwxyziflskecznslkjfabe"));
    }
}
