package org.exercism.java.exercises.concept.pangram;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

public class PangramTest {
    @Test
    void pangram() {
        assertThat(new Pangram("The quick brown fox jumps over the lazy dog.").isPangram()).isTrue();
    }

    @Test
    void pangram_with_special_characters() {
        assertThat(new Pangram("The quick brown fox jumps over the lazy dog, what a nice day!").isPangram()).isTrue();
    }

    @Test
    void pangram_with_spaces() {
        assertThat(new Pangram("The quick brown fox jumps over the lazy dog    ").isPangram()).isTrue();
    }

    @Test
    void pangram_with_special_characters_and_spaces() {
        assertThat(new Pangram("The quick brown fox jumps over the lazy dog, what a nice day!   ").isPangram()).isTrue();
    }

    @Test
    void not_pangram() {
        assertThat(new Pangram("The quick brown fox jumps over the lazy dog, what a nice day!   ").isPangram()).isFalse();
    }
}
