package com.example.codewithme.codewithme

import android.content.Intent
import android.support.v7.app.AppCompatActivity
import android.os.Bundle
import android.view.View
import android.widget.Button
import android.widget.EditText
import android.widget.TextView

class CodeWithMeActivity : AppCompatActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_code_with_me)

        val button = findViewById<Button>(R.id.start_button)
        val loginButton = findViewById<Button>(R.id.login_button)
        val username = findViewById<EditText>(R.id.username_edit)
        val password = findViewById<EditText>(R.id.password_edit)
        val error = findViewById<TextView>(R.id.error_text)

        button.setOnClickListener{
            if(username.text.toString()!= getString(R.string.username) || password.text.toString()!= getString(R.string.password)){
                error.text = getString(R.string.error)
            }else{
                val intent = Intent(this, ChooseLanguageActivity::class.java)
                startActivity(intent)
            }
        }

        loginButton.setOnClickListener{
            val intent = Intent(this, LoginActivity::class.java)
            startActivity(intent)
        }
    }
}
