public class SocketServerTest {

    private static final int SERVER_PORT = 4000;

    private static ServerSocket serverSocket;

    @BeforeAll
    public static void setUp() throws IOException {
        serverSocket = new ServerSocket(SERVER_PORT);
    }

    @AfterAll
    public static void tearDown() throws IOException {
        serverSocket.close();
    }

    @Test
    public void it_should_accept_one_connection_and_close_it() throws IOException {
        SocketServer server = new SocketServer(SERVER_PORT);
        server.start();

        assertThat(serverSocket.isClosed()).isFalse();

        server.stop();

        assertThat(serverSocket.isClosed()).isTrue();
    }
