    if (!payloadMap.get("typ").equals("JWT")) {
        return false;
    }
    return true;
}

private static boolean verifySignature(String payload, String signature) {
    return signature.equals(Base64.getEncoder().encodeToString(messageDigest(payload)));
}

private static Map<String, Object> decode(String input) {
    Map<String, Object> map = new HashMap<>();
    for (String part : input.split("\\.")) {
        String[] keyValue = part.split("\\=");
        map.put(keyValue[0], keyValue[1]);
    }
    return map;
}

private static byte[] messageDigest(String payload) {
    return new String(payload).getBytes();
}
