function loadFromUrl() {
    let hash = window.location.hash;
    if (hash) {
        let params = hash.substr(1).split('&');
        let data = {};
        params.forEach(param => {
            let [key, value] = param.split('=');
            data[key] = decodeURIComponent(value);
        });
        if (data.code) {
            let code = data.code;
            let id = data.id;
            let input = document.getElementById(id);
