package com.github.misterbrown.ppl.utils;

import java.io.IOException;
import java.io.InputStream;

/**
 * An InputStream that reads from a byte array.
 */
public class ByteArrayInputStream extends InputStream {
    private final byte[] bytes;
    private int pos;
    private int bytesRead;

    /**
     * Creates a new ByteArrayInputStream using the specified byte array.
     * 
     * @param bytes the byte array to read from
     */
    public ByteArrayInputStream(byte[] bytes) {
        this.bytes = bytes;
    }

    @Override
    public int read() throws IOException {
        if (pos >= bytes.length) {
            return -1;
        }

        bytesRead++;

        return bytes[pos++] & 0xFF;
    }

    @Override
    public int read(byte[] b) throws IOException {
        return read(b, 0, b.length);
    }

    @Override
    public int read(byte[] b, int off, int len) throws IOException {
        if (pos >= bytes.length) {
            return -1;
        }

        int toRead = Math.min(len, bytes.length - pos);
        bytesRead += toRead;

        System.arraycopy(bytes, pos, b, off, toRead);
        pos += toRead;

        return toRead;
    }

    @Override
    public int available() throws IOException {
        return bytes.length - pos;
    }

    @Override
    public void close() throws IOException {
    }

