import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.List;

import javax.transaction.Transactional;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.Resource;
import org.springframework.core.io.ResourceLoader;
import org.springframework.stereotype.Service;

import com.github.panda114.onlinejudge.model.Submission;
import com.github.panda114.onlinejudge.repository.SubmissionRepository;
import com.github.panda114.onlinejudge.service.SubmissionService;

@Service
@Transactional
public class SubmissionServiceImpl implements SubmissionService {

	@Autowired
	private SubmissionRepository submissionRepository;

	@Autowired
	private ResourceLoader resourceLoader;

	@Value("${submission.tempdir}")
	private String tempdir;

	@Override
	public List<Submission> findByLanguage(Long languageId) {
		return submissionRepository.findByLanguageId(languageId);
	}

	@Override
	public String getSubmissionContent(Long submissionId) {
		Submission submission = submissionRepository.findById(submissionId).orElse(null);

		if (submission!= null) {
			Resource resource = resourceLoader.getResource(submission.getPath());

			try {
				return new String(Files.readAllBytes(Paths.get(tempdir, resource.getFilename())));
			} catch (Exception e) {
				throw new RuntimeException(e.getMessage());
			}
		}

		return null;
	}

}
