		boolean[] isComposite = new boolean[max + 1];
		List<Integer> primes = new ArrayList<Integer>();
		for (int i = 2; i <= max; i++) {
			if (!isComposite[i]) {
				primes.add(i);
				for (int j = i * i; j <= max; j += i) {
					isComposite[j] = true;
				}
			}
		}
		return primes;
	}
