            String algorithm = key.length() == 16? "AES" : "DES";
            // maak een geheugengeheugen object met de gekozen sleutel
            SecretKeySpec secretKey = new SecretKeySpec(key.getBytes(), algorithm);
            // maak een Cipher object met de gekozen sleutel
