            // maak een byte array met de geheugengeheugen object
            byte[] bytes = data.getBytes();
            // maak een byte array met de gekozen Cipher object
            byte[] encrypted = cipher.doFinal(bytes);
            // returneer het versleutelde byte array
            return new String(encrypted);
        } catch (Exception e) {
            return null;
        }
    }
}
