import nl.tudelft.contextproject.model.ClassModel;
import nl.tudelft.contextproject.model.UserModel;

/**
 *
 * @author 
 */
public class CreateClassAction extends Action {

    @Override
    public String execute(HttpServletRequest request, HttpServletResponse response) {
        UserModel user = (UserModel) request.getSession().getAttribute("user");
        String name = request.getParameter("name");
        String code = request.getParameter("code");
        String language = request.getParameter("language");
        String teacher = request.getParameter("teacher");

        List<ClassModel> classes = ClassModel.findClassModelsByTeacher(user.getUsername());
        for (ClassModel c : classes) {
            if (c.getName().equals(name)) {
                request.setAttribute("error", "Class name already exists.");
                return "error.jsp";
            }
        }

        ClassModel classModel = new ClassModel(name, code, language, user.getUsername());
        classModel.save();
        return "classes.jsp";
    }
}
