package at.ac.tuwien.ifs.mei.sabc.util;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Util {
    public static String capitalize(String str) {
        return str.substring(0, 1).toUpperCase() + str.substring(1);
    }

    public static String convertPath(String path) {
        return path.replaceAll("\\\\", "/");
    }

    public static String convertLineEndings(String content) {
        return content.replaceAll("\r\n", "\n");
    }

    public static String convertTabs(String content, int tabSize) {
        String tab = " ".repeat(tabSize);
        return content.replaceAll("\t", tab);
    }

    public static String removeComments(String content) {
        String[] lines = content.split("\n");
        StringBuilder result = new StringBuilder();
        for (String line : lines) {
            if (line.contains("//")) {
                line = line.substring(0, line.indexOf("//"));
            }
            result.append(line).append("\n");
        }
        return result.toString();
    }

    public static String replace(String content, String pattern, String replacement) {
        Pattern r = Pattern.compile(pattern);
        Matcher m = r.matcher(content);
        return m.replaceAll(replacement);
    }
}
