public class StringList {

    private String value;
    private StringList next;

    public StringList(String value, StringList next) {
        this.value = value;
        this.next = next;
    }

    public String getValue() {
        return value;
    }

    public StringList getNext() {
        return next;
    }

    public StringList find(String value) {
        if (value.equals(this.value)) {
            return this;
        }

        if (next == null) {
            return null;
        }

        return next.find(value);
    }

    public StringList insert(String value) {
        if (this.value.compareTo(value) >= 0) {
            return new StringList(value, this);
        }

        if (next == null) {
            return new StringList(value, null);
        }

        return new StringList(value, next.insert(value));
    }

    public StringList delete(String value) {
        if (value.equals(this.value)) {
            return next;
        }

        if (next == null) {
            return null;
        }

        if (next.value.equals(value)) {
            return next.next;
        }

        next.next = next.delete(value);
        return this;
    }

