struct Node {
  char *key;
  int value;
  struct Node *next;
};

struct Node *root = NULL;

struct Node *new_node(char *key, int value) {
  struct Node *n = malloc(sizeof(struct Node));
  n->key = key;
  n->value = value;
  n->next = NULL;
  return n;
}

void add_node(char *key, int value) {
  struct Node *n = new_node(key, value);
  n->next = root;
  root = n;
}

struct Node *find_node(char *key) {
  struct Node *n = root;
  while (n!= NULL) {
    if (strcmp(n->key, key) == 0) {
      return n;
    }
    n = n->next;
  }
  return NULL;
}

void print_node(struct Node *n) {
  printf("Key: %s, Value: %d\n", n->key, n->value);
}

void print_list() {
  struct Node *n = root;
  while (n!= NULL) {
    print_node(n);
    n = n->next;
  }
}

