package com.github.paulohff.exercism.java.pangram;

import java.util.regex.Pattern;

/**
 * Class that checks if a sentence is a pangram or not.
 * 
 * @author 
 */
public class Pangram {

    private static final Pattern pattern = Pattern.compile("[a-z]*");

    /**
     * Checks whether the given sentence is a pangram or not.
     * 
     * A pangram is a sentence containing all the letters of the alphabet.
     * 
     * @param sentence the sentence to check
     * @return true if the sentence is a pangram
     */
    public boolean isPangram(final String sentence) {
        String normalized = sentence.toLowerCase();
        normalized = pattern.matcher(normalized).replaceAll("");
        return normalized.length() == 26;
    }
}
