public class Event {

    private List<Consumer<Event>> consumers;

    public Event() {
        this.consumers = new ArrayList<>();
    }

    public Event(List<Consumer<Event>> consumers) {
        this.consumers = consumers;
    }

    public void addConsumer(Consumer<Event> consumer) {
        this.consumers.add(consumer);
    }

    public void removeConsumer(Consumer<Event> consumer) {
        this.consumers.remove(consumer);
    }

    public void callConsumers() {
        for (Consumer<Event> consumer : this.consumers) {
            consumer.accept(this);
        }
    }
}
