        blackListedDomains.add("www.linkedin.com");
        blackListedDomains.add("www.reddit.com");

        for (String blackListedDomain : blackListedDomains) {
            if (domain.contains(blackListedDomain)) {
                return;
            }
        }

        try {
            if (!domain.contains("http://") &&!domain.contains("https://")) {
                domain = "http://" + domain;
            }
            URI uri = new URI(domain);
            response.sendRedirect(uri);
        } catch (URISyntaxException e) {
            e.printStackTrace();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
