        return lines;
    }

    public void setLines(List<CodeLine> lines) {
        this.lines = lines;
    }

    public void addLine(CodeLine line) {
        lines.add(line);
    }

    public void addLine(String line) {
        addLine(new CodeLine(line));
    }

