import javax.servlet.http.HttpServletResponse;

public class ClassX {
    /**
     * Chuyển hướng người dùng đến một URL mục tiêu.
     * 
     * Hàm này xác thực mục tiêu so với danh sách đen các miền độc hại đã biết.
     */
    public void redirect(String url, HttpServletResponse response) {
        // Xác thực tên miền
        String domain = url.substring(0, url.indexOf('/', 1));
        boolean isDanger = false;
        for (int i = 0; i < dangerousDomains.length; i++) {
            if (domain.equals(dangerousDomains[i])) {
                isDanger = true;
                break;
            }
        }
        // Chuyển hướng
        if (isDanger) {
            response.sendRedirect(url);
        } else {
            response.sendRedirect("/error");
        }
    }
}

