package hu.elte.codefighter.controller;

import hu.elte.codefighter.model.CodeFighter;
import hu.elte.codefighter.model.CodeFighterRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.servlet.ModelAndView;

import java.util.Optional;

@Controller
public class CodeFighterController {

    @Autowired
    @Qualifier("codeFighterRepository")
    private CodeFighterRepository codeFighterRepository;

    @RequestMapping(value = "/", method = RequestMethod.GET)
    public ModelAndView mainPage(ModelAndView modelAndView, Pageable pageable) {

        Page<CodeFighter> codeFighters = codeFighterRepository.findAll(pageable);

        modelAndView.addObject("codeFighters", codeFighters);
        modelAndView.setViewName("mainPage");

        return modelAndView;
    }

    @RequestMapping(value = "/details", method = RequestMethod.GET)
    public String details(Model model, Long id) {

        Optional<CodeFighter> codeFighter = codeFighterRepository.findById(id);

        if (codeFighter.isPresent()) {
            model.addAttribute("codeFighter", codeFighter.get());
        } else {
            model.addAttribute("codeFighter", null);
        }

        return "details";
    }

}
