public static boolean isValidHost(String host) {
    String[] blackList = {
        "microsoft.com",
        "google.com",
        "ebay.com",
        "amazon.com",
        "yahoo.com",
        "facebook.com",
        "twitter.com",
        "bing.com"
    };
