public class Level {
    private Tile[][] tiles;

    /**
     * Create a Level with a given number of rows and columns.
     * 
     * @param rows    the number of rows in the Level
     * @param columns the number of columns in the Level
     */
    public Level(int rows, int columns) {
        tiles = new Tile[rows][columns];
    }

    /**
     * Set a Tile at a given row and column.
     * 
     * @param row   the row of the Tile
     * @param col   the column of the Tile
     * @param tile  the Tile to set
     */
    public void setTile(int row, int col, Tile tile) {
        tiles[row][col] = tile;
    }

    /**
     * Get a Tile at a given row and column.
     * 
     * @param row the row of the Tile
     * @param col the column of the Tile
     * 
     * @return the Tile at row, col
     */
    public Tile getTile(int row, int col) {
        return tiles[row][col];
    }

    /**
     * Get the number of rows in the Level.
     * 
     * @return the number of rows
     */
    public int getRows() {
        return tiles.length;
    }

    /**
     * Get the number of columns in the Level.
     * 
     * @return the number of columns
     */
    public int getColumns() {
        return tiles[0].length;
    }

    /**
     * Get the Level as a 2D array of Tiles.
     * 
     * @return the Level as a 2D array of Tiles
     */
    public Tile[][] getTiles() {
        return tiles;
    }
}
