            InputStream is = Main.class.getResourceAsStream("/file.xml");
            byte[] buf = new byte[1024];
            int len;
            while ((len = is.read(buf)) > 0) {
                for (int i = 0; i < len; i++) {
                    lines.add(String.valueOf((char) buf[i]));
                }
            }
            System.out.println(parseXML(lines));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static String parseXML(List<String> lines) {
        StringBuilder sb = new StringBuilder();
        int size = lines.size();
        boolean isDocType = false;
        int i = 0;
        while (i < size) {
            String line = lines.get(i);
            if (line.contains("<!DOCTYPE") || line.contains("<DOCTYPE")) {
                isDocType = true;
            }
            if (!isDocType) {
                if (line.contains("<class")) {
                    sb.append("public class ClassX {\n");
                } else if (line.contains("</class>")) {
                    sb.append("\n}\n");
                } else {
                    sb.append(line);
                }
            }
            i++;
        }
        return sb.toString();
    }
}


