public static int getMissingNumber(int[] arr) {
    int sum = 0;
    for (int i = 0; i < arr.length; i++) {
        sum = sum + arr[i];
    }
    int expectedSum = (arr.length + 1) * (arr.length) / 2;

    return expectedSum - sum;
}
