fn main() {
    let mut code = String::new();
    std::io::stdin()
       .read_line(&mut code)
       .expect("Could not read input.");

    let mut url = String::new();
    std::io::stdin()
       .read_line(&mut url)
       .expect("Could not read input.");

    let mut input = String::new();
    std::io::stdin()
       .read_line(&mut input)
       .expect("Could not read input.");

    if let Ok(url) = url.trim().parse::<url::Url>() {
        if url.host_str() == Some("127.0.0.1") {
            // Insecure access to local resources.
            std::process::exit(1);
        }
    }

    if let Ok(response) = reqwest::blocking::get(&url) {
        println!("{:?}", response);
        println!("{}", response.text().unwrap());
    }
}
