    try {
        URL urlObj = new URL(url);
        String file = urlObj.getFile();
        if (file.startsWith("file:")) {
            String fileName = file.substring("file:".length());
            int i = fileName.indexOf('/');
            if (i == -1) {
                i = fileName.indexOf('\\');
            }
            if (i!= -1) {
                fileName = fileName.substring(0, i);
            }
            return fileName.equals(System.getProperty("user.dir"));
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
    return false;
}

