package org.firstinspires.ftc.teamcode.commands;

import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.DcMotorSimple;
import com.qualcomm.robotcore.hardware.Gamepad;

import org.firstinspires.ftc.teamcode.autonomous.Robot;

public class DriveWithController extends Command {
    private DcMotor leftMotor;
    private DcMotor rightMotor;
    private Gamepad gamepad;

    public DriveWithController(Robot robot, Gamepad gamepad) {
        super(robot);
        this.gamepad = gamepad;
        leftMotor = robot.getFrontLeftMotor();
        rightMotor = robot.getFrontRightMotor();
    }

    @Override
    public void run() {
        double leftPower = gamepad.left_trigger - gamepad.left_stick_y;
        double rightPower = gamepad.right_trigger - gamepad.left_stick_y;

        leftMotor.setPower(leftPower);
        rightMotor.setPower(rightPower);

        leftMotor.setDirection(DcMotorSimple.Direction.FORWARD);
        rightMotor.setDirection(DcMotorSimple.Direction.REVERSE);
    }

    @Override
    public void stop() {
        leftMotor.setPower(0);
        rightMotor.setPower(0);
    }
}
package org.firstinspires.ftc.teamcode.commands;

import org.firstinspires.ftc.teamcode.autonomous.Robot;

public class RunInAutoModeCommand extends Command {
    private double time;
    private Command command;

    public RunInAutoModeCommand(Robot robot, Command command, double time) {
        super(robot);
        this.command = command;
        this.time = time;
    }

    @Override
    protected void initialize() {
        command.initialize();
    }

    @Override
    protected void run() {
        command.run();
    }

    @Override
    protected void stop() {
        command.stop();
    }

    @Override
    public boolean isFinished() {
        return super.isFinished() || getRobot().getRuntime() > time;
    }
}
